"""Explain lockref storage, CAS retries and reference acquisition."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1385': ('물건을 사용하는 사람 수와 장부를 고치는 중이라는 표시를 한 카드에 적어 봅시다. 숫자만 확인하면 잠금 표시가 바뀐 것을 놓칠 수 있으므로 두 정보를 함께 확인합니다.', 'lockref가 잠금과 참조 수를 같은 비교 범위에 두는 이유를 배웁니다.', '카드에 잠금=풀림, count=3을 적으세요. 숫자를 4로 바꾸려는 사이 다른 사람이 잠금=사용 중으로 바꾸면, 카드 전체 비교는 실패한다고 표시하세요.', ['참조는 객체를 계속 사용하겠다는 약속입니다. count는 그런 참조의 수를 나타냅니다. lockref에는 그 수와 함께 spinlock이라는 잠금이 있습니다. 여러 실행 흐름이 이 정보를 함께 다룰 때 서로의 변경을 망가뜨리지 않도록 합니다.', '일반적인 길은 잠금을 얻고 count를 고친 뒤 푸는 것입니다. lockref에는 조건이 맞으면 잠금을 실제로 잡지 않고도 갱신하는 최적화가 있습니다. 그 경우에도 잠금 상태를 무시하지 않고 count와 함께 비교합니다.', 'CAS는 비교한 값이 여전히 같을 때만 새 값으로 바꾸는 연산입니다. 여기서는 잠금과 count를 담은 8바이트 전체가 비교 대상입니다. 읽은 뒤 다른 쪽이 잠금만 바꿔도 전체가 달라져 CAS가 실패할 수 있습니다.', '이 최적화에는 CONFIG_ARCH_USE_CMPXCHG_LOCKREF 설정, CONFIG_SMP 설정, SPINLOCK_SIZE가 4 이하라는 조건이 모두 필요합니다. CONFIG는 커널을 만들 때 고르는 기능입니다. 실행 중 count가 1인지로 최적화가 켜지는 것이 아닙니다.', 'union은 같은 저장 공간을 다른 모양으로 볼 수 있게 하는 C 문법입니다. lock_count라는 64비트 값과 lock·count 구조가 겹칩니다. 두 개의 독립된 count 사본을 나중에 맞추는 방식이 아닙니다. aligned_u64는 필요한 정렬에 맞춘 64비트 표현입니다.', '최적화 조건이 없으면 합친 lock_count 원소도 없고, get 같은 함수는 실제 spinlock 경로를 사용합니다. 함수마다 뒤의 처리가 다르므로 API별 본체를 확인해야 합니다. 이 구조가 객체 수명이나 count 범위까지 자동으로 검증하는 것은 아닙니다.'], [('CAS 최적화를 켜는 조건은 무엇일까요?', ['count가 1이면 언제나 켜져요', '아키텍처 설정·SMP·작은 spinlock 크기가 함께 맞아야 해요'], '헤더는 세 가지 빌드 조건을 확인합니다. 프로그램 실행 중 바뀌는 참조 수와 커널을 만들 때 선택하는 구현 조건은 다릅니다.'), ('union 안의 lock_count는 무엇과 같은 공간을 사용할까요?', ['lock과 count를 담은 구조와 겹쳐요', '따로 저장된 count 복사본이에요'], '같은 바이트를 합친 숫자로도, 잠금과 수로도 보는 것입니다. 그래서 한 번의 비교에 두 상태를 포함할 수 있습니다.')]), 'os1386': ('장부에 3이라고 읽고 4로 고치려는데 다른 사람이 먼저 4로 만들었다면, 다시 4를 바탕으로 5를 계산해야 두 번의 증가가 모두 반영됩니다.', 'CAS 실패 뒤 최신 값으로 다시 계산하는 과정과 재시도 한도를 이해합니다.', 'A가 3을 읽음 → B가 4로 변경 → A의 3에서 4로 바꾸기 실패 → A의 old가 4로 갱신 → 새 후보 5로 재시도 순서를 쓰세요.', ['CMPXCHG_LOOP는 여러 lockref 함수가 함께 쓰는 매크로입니다. CODE에는 시도할 계산, SUCCESS에는 성공했을 때 할 일이 들어갑니다. 글처럼 펼쳐지는 규칙이므로 실제 호출 함수에 들어간 두 부분을 함께 읽어야 합니다.', '먼저 retry를 100으로 두고 잠금과 count를 합친 값을 old에 읽습니다. 구조 크기가 8바이트인지 BUILD_BUG_ON으로 확인합니다. 이 확인은 실행 중 오류 반환이 아니라 빌드할 때 잘못된 구조를 잡는 장치입니다.', '읽은 잠금이 풀려 있는 동안 old를 new에 복사해 CODE를 실행합니다. 그리고 try_cmpxchg64_relaxed로 실제 값이 old와 같은지 비교합니다. 같으면 new로 바꾸고 SUCCESS를 실행합니다. old와 new는 실제 객체와 구별되는 지역 복사본입니다.', '비교가 실패하면 try_cmpxchg가 old를 실제로 관측한 값으로 갱신합니다. 다음 반복은 그 old로 new를 다시 만듭니다. 3에서 증가하려다 실제 값 4를 발견했다면 4를 바탕으로 5를 계산해야 다른 사람의 증가를 잃지 않습니다.', '실패 때 retry를 하나 줄입니다. 계속 잠금이 풀려 있고 계산이 조기 종료하지 않는 경우, CAS 실패가 100번 쌓이면 반복을 벗어납니다. 관측한 잠금이 잡혀 있거나 CODE에서 빠져나오는 경우에는 더 일찍 끝날 수 있습니다.', '반복 뒤의 처리는 함수마다 다릅니다. lockref_get은 실제 spinlock으로 이어지지만 lockref_put_return은 실패 -1을 돌려줍니다. relaxed CAS라는 이름은 보호할 모든 데이터의 acquire·release 순서까지 보장한다는 뜻이 아닙니다. 같은 상태의 원자적 비교와 데이터 접근 순서를 구별하세요.'], [('CAS에 실패한 뒤 다음 계산에 사용하는 old는 무엇일까요?', ['처음 읽은 값으로 계속 고정돼요', '실패한 CAS가 갱신한 관측값이에요'], 'try_cmpxchg는 비교 실패 때 예상값 old를 관측값으로 바꿉니다. 다음 반복이 new를 다시 만들므로 바뀐 count를 반영할 수 있습니다.'), ('100번 실패해 반복을 나오면 모든 함수가 같은 일을 할까요?', ['아니요. 매크로 뒤에 있는 함수별 코드가 달라요', '네. 무조건 수를 바꾸고 성공해요'], 'get은 spinlock으로 증가를 수행하지만 put_return은 실패를 반환합니다. 반복을 나왔다는 사실만으로 변경이나 성공을 단정하면 안 됩니다.')]), 'os1387': ('이미 빌린 물건을 다른 작업에서도 계속 쓰려고 사용 약속을 하나 더 기록합니다. 버려진 물건의 옛 주소만 보고 약속 수를 늘릴 수는 없습니다.', 'lockref_get의 참조 보유 전제와 증가 경로를 이해합니다.', '이미 참조를 가진 상태에서 count=2라고 적으세요. get으로 3이 됩니다. CAS로 못 바꾸면 잠금을 얻고 현재 count를 하나 늘린 뒤 잠금을 푼다고 그리세요.', ['lockref_get은 참조 수를 하나 늘립니다. 원문은 호출자가 이미 그 객체의 참조를 가지고 있어야 한다고 설명합니다. 그 약속으로 객체가 사라지지 않고 count가 0이 아님을 알아야 합니다.', '먼저 가능한 환경에서 CAS 반복을 시도합니다. new.count++는 지역 복사본 new의 수를 하나 늘리는 식입니다. 아직 실제 객체에 썼다는 뜻은 아닙니다. CAS가 성공해야 그 새 상태가 실제 객체에 반영됩니다.', 'CAS가 성공하면 return으로 함수를 끝냅니다. 성공하지 못해 뒤로 내려오면 spin_lock(&lockref->lock)으로 잠금을 얻습니다. 다른 실행 흐름의 변경과 충돌하지 않도록 실제 잠금을 쓰는 길입니다.', '잠금을 얻은 상태에서 lockref->count++로 실제 수를 하나 늘리고 spin_unlock으로 풉니다. 최적화가 없는 환경에서도 이 경로가 있으므로 get 기능 자체가 사라지는 것은 아닙니다.', '처음 count=2이고 다른 변경이 없다면 get 뒤에는 3입니다. 반환형 void는 결과 숫자를 돌려주지 않는다는 뜻입니다. count 증가 성공을 새 주소 검사나 이미 끝난 객체의 부활 기능으로 생각하면 안 됩니다.', '이 함수에는 죽은 객체와 정수 넘침을 모두 안전하게 거절하는 검사가 없습니다. 이미 참조를 보유한 유효한 객체와 int 범위 안의 count라는 사용 조건을 지켜야 합니다. count가 존재한다고 객체 메모리 수명 문제까지 자동 해결되지는 않습니다.'], [('lockref_get을 부르기 전에 어떤 조건이 필요할까요?', ['해제된 객체의 주소만 기억하면 돼요', '이미 객체의 참조를 보유하고 있어야 해요'], '이미 가진 참조로 객체가 살아 있음을 알아야 합니다. 해제된 주소에 수를 써서 객체를 다시 살리는 함수가 아닙니다.'), ('CAS 최적화가 없는 환경에서 get은 어떻게 증가할까요?', ['spinlock을 잡고 count를 늘린 뒤 풀어요', '항상 아무 변경 없이 실패해요'], '매크로 부분을 지나면 잠금·증가·해제 코드가 있습니다. 빠른 경로가 없어도 일반 경로가 기능을 수행합니다.')]), 'os1388': ('사용 약속이 아직 남아 있는 물건에만 약속 하나를 더 붙여 봅시다. 끝났다는 표시가 있는 물건은 숫자를 늘려 되살리지 않습니다.', '양수 조건과 성공 여부 반환을 새 참조 수와 구별합니다.', 'count가 -128, 0, 3인 세 줄 표를 만드세요. 다른 변경이 없을 때 결과는 각각 유지·유지·4이고 반환은 0·0·1입니다.', ['lockref_get_not_zero는 이름처럼 단순히 0만 검사하는 것보다 조건이 넓습니다. count가 양수일 때만 하나 늘립니다. 0과 음수는 거절합니다. 이 lockref 규칙에서 음수는 dead, 즉 더 이상 정상 참조를 얻지 못하게 한 상태입니다.', 'CAS 경로는 new.count++로 후보 복사본을 만든 다음 old.count <= 0인지 확인합니다. 조건에 걸리면 0을 반환하므로 후보가 실제 객체에 저장되지 않습니다. 지역 숫자를 계산한 것과 실제 count가 증가한 것은 다릅니다.', '양수라면 CAS 성공 때 1을 반환합니다. CAS를 사용할 수 없거나 반복에서 빠져나오면 spinlock을 잡고 현재 count > 0인 경우에만 실제 수를 늘립니다. 두 경로 모두 양수 조건을 지킵니다.', '다른 실행 흐름의 변경이 없을 때 count=-128은 그대로이고 반환은 0입니다. count=0도 그대로입니다. count=3이면 4로 바뀌지만 반환은 1입니다. 반환값은 새 count가 아니라 성공 여부입니다.', '실패 0이 현재 count가 꼭 0이라는 뜻도 아닙니다. 음수 상태를 보고 실패했을 수도 있습니다. 성공한 경우에만 새 참조를 얻었다고 판단하고 그 참조에 맞는 사용·반납 규칙을 이어 가야 합니다.', '조건부 증가 함수도 잘못된 주소를 안전하게 검사하는 도구는 아닙니다. 검사하는 동안 객체 메모리가 유효하다는 별도의 수명 보호가 필요합니다. 양수라도 int 범위를 넘는 증가까지 자동으로 방지하는 것은 아니므로 수의 유효 범위도 지켜야 합니다.'], [('count=-128이면 이 함수는 어떤 결과를 낼까요?', ['-127로 늘리고 성공해요', '실패 0을 반환하며 이 호출은 count를 바꾸지 않아요'], '검사식은 old.count <= 0입니다. -128도 조건에 포함되므로 실제 객체에 증가 후보를 저장하지 않습니다. 이름만 보고 음수를 허용한다고 생각하면 틀립니다.'), ('성공 반환 1은 새 count가 1이라는 뜻일까요?', ['아니요. 증가에 성공했다는 표시예요', '네. 새 count는 반드시 1이에요'], '예를 들어 기존 3은 4가 되지만 함수의 반환은 1입니다. 실제 수와 성공 여부라는 두 종류의 정보를 구별해야 합니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_342.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
